NAME = 'FreLXXGiguet: Traduction de la LXX par Pierre GIGUET et autres traducteurs, 1872.'
BOOK = 'Psalms of Solomon'

CHAPTERS = {
    1: {
        1: 'J’ai poussé des cris vers le Seigneur lorsque j’étais dans la tribulation, j’ai crié vers Dieu lorsque les pécheurs me persécutaient,',
        2: 'Le tumulte de la guerre s’est subitement fait entendre devant moi, le Seigneur m’a écouté parce que je suis plein de justice.',
        3: 'J’ai pensé dans mon cœur que j’étais plein de justice, dans l’abondance et dans la multitude des fils.',
        4: 'Leurs richesses sont parvenues dans toute la terre, et leur gloire s’est répandue jusqu’aux extrémités de la terre.',
        5: 'Ils ont été élevés jusqu’aux astres; ils ont dit qu’ils ne pouvaient tomber.',
        6: 'Ils ont été dans l’abondance des biens et ils n’ont point apporté d’offrandes.',
        7: 'Leurs iniquités ont été commises dans les lieux cachés, et je ne les ai pas connues.',
        8: 'Leurs iniquités sur les nations qui les avaient précédés ont profané le sanctuaire du Seigneur en le souillant.',
    },
    2: {
        1: 'Le pécheur s’est enorgueilli de son pouvoir; il est venu avec des machines renverser des murailles, et tu ne l’en a pas empêché.',
        2: 'Les nations étrangères sont montées à ton autel; elles marchaient avec orgueil, et leurs chaussures foulaient le sanctuaire.',
        3: 'Parce que les fils d’Israël ont souillé le sanctuaire du Seigneur; ils ont profané les dons de Dieu dans leurs iniquités.',
        4: 'C’est pourquoi il a dit: Rejetez loin de moi ces offrandes, qui n’ont point le parfum de la douceur; la beauté de la gloire du Seigneur n’y est point,',
        5: 'Ils ont été réduits au néant devant Dieu, leur fin a été déshonorée.',
        6: 'Les fils et les filles (des pécheurs) seront conduits dans une dure captivité, leur tête sera marqué d’un stigmate comme un signe parmi les nations.',
        7: 'Dieu les as traités selon leur iniquité, car il les a abandonnés aux mains des forts.',
        8: 'Car il a détourné sa face de la miséricorde qu’il avait eue sur eux; le jeune homme et le vieillard et leurs fils ont été frappés ensemble,',
        9: 'Parce que les impies ont agi d’accord pour ne pas entendre (la parole du Seigneur.)',
        10: 'Et le ciel s’est irrité, et la terre les a eus en abomination.',
        11: 'Parce que nul homme n’a fait ce qu’ils ont fait.',
        12: 'Et la terre connaîtra tes jugements; elle connaîtra toutes tes justices, ô mon Dieu; tu as fait des fils de Jérusalem un objet le division à cause des fornications qui se commettaient en son enceinte.',
        13: 'Tout homme qui marche dans l’iniquité, marche contre le soleil (c’est-à-dire, rommet des fautes qui seront mises au grand jour); ils se raillaient de ses iniquités.',
        14: 'Ce qu’ils ont fait contre le soleil servira de modèle pour le traitement réservé à leurs iniquités, et les filles de Jérusalem seront souillées selon ton jugement.',
        15: 'Parce qu’elles se sont souillées elles-mêmes par l’approche du mélange (avec les étrangers).',
        16: 'Je proclamerai ta justice, Seigneur, dans la droiture de mon cœur; ta justice céleste, Seigneur, dans tes jugements.',
        17: 'Car tu as traité les pécheurs selon leurs crimes et selon leurs péchés dont la griéveté est extrême.',
        18: 'Tu as révélé leurs péchés, afin que ton jugement paraisse.',
        19: 'Tu as effacé leur mémoire de dessus la terre, Seigneur, qui juge avec justice, et tu ne fais acception de personne.',
        20: 'Il a arraché son éclat de dessus le trône de majesté, parce que les nations ont raillé Jérusalem en la foulant aux pieds.',
        21: 'Il a pris un sac pour vêtement d’honneur; il a mis une corde autour de sa tête en guise de couronne.',
        22: 'Il a enlevé le diadème de gloire que Dieu lui avait imposé.',
        23: 'La beauté a été renversée à terre dans l’ignominie.',
        24: 'Et j’ai vu ces choses, et j’ai prié la face du Seigneur, et j’ai dit: Qu’il te suffise, Seigneur, d’appesantir la main sur Jérusalem dans la captivité des nations.',
        25: 'Parce qu’elles se railleront de Jérusalem, et que dans leur colère et leur fureur pleine d’emportement, elles ne l’épargneront pas.',
        26: 'Et elles la consumeront, à moins que toi, Seigneur, tu ne les gourmandes dans ta colère.',
        27: 'Parce qu’elles ne l’ont pas fait par suite de zèle, mais dans la concupiscence de l’âme.',
        28: 'Pour qu’elles répandent leur colère sur nous dans la rapine, ne diffère pas, mon Dieu, de faire tomber la rétribution sur leurs têtes.',
        29: 'Afin qu’elles aient l’orgueil du dragon tombé dans l’ignominie.',
        30: 'Et je n’ai pas attendu jusqu’à ce que Dieu m’ait montré son opprobre; il a été frappé dans les montagnes d’Egypte, et il disparaîtra de dessus la terre et la mer.',
        31: 'Son cadavre, devenu la proie de la pourriture, sera le jouet des flots et couvert d’ignominie; il n’y aura personne pour l’ensevelir.',
        32: 'Parce que le Seigneur l’a réduit au néant dans l’ignominie; il n’a pas pensé qu’il était homme, et il n’a pas songé à sa fin.',
        33: 'Il a dit: Je serai le Seigneur de la terre et de la mer, et il n’a pas su que le Dieu grand était puissant dans sa force.',
        34: 'Il est le roi dans les cieux; il juge les rois et les principautés.',
        35: 'Il me rétablira dans la gloire et fera dormir les superbes dans la perdition éternelle et dans l’ignominie, parce qu’ils ne l’ont pas connu.',
        36: 'Et maintenant, grands de la terre, voyez le jugement du Seigneur; il est le Roi juste et grand qui juge sous le ciel.',
        37: 'Bénissez Dieu, vous qui craignez le Seigneur et qui savez que la miséricorde du Seigneur s’étend sur ceux qui le craignent dans ses jugements.',
        38: 'Pour qu’il discerne entre le juste et le pécheur et qu’il rétribue les pécheurs pour l’éternité selon leurs œuvres.',
        39: 'Et qu’il ait compassion du juste, prenant en considération l’humilité du pécheur, et qu’il traite le pécheur selon ce qu’il a fait au juste.',
        40: 'Parce que le Seigneur est plein de bonté pour ceux qui l’invoquent dans la patience, pour qu’il agisse selon sa miséricorde à l’égard de ceux qui sont toujours en sa présence.',
        41: 'Béni soit le Seigneur dans l’éternité en présence de ses serviteurs.',
    },
    3: {
        1: 'Pourquoi dors-tu, mon âme, et pourquoi ne bénis-tu pas le Seigneur?',
        2: 'Chantez un hymne nouveau en l’honneur de Dieu digne de louange; chantez et veillez, adressez à Dieu un cantique du fond de votre cœur.',
        3: 'Les justes se souviennent toujours du Seigneur; ils confessent la justice de ses jugements.',
        4: 'Le juste repris par le Seigneur, ne tombera pas dans la négligence; sa pensée sera toujours devant le Seigneur.',
        5: 'Dans ses calamités le juste reconnaît la justice de Dieu, et dans ses malheurs il attend l’appui du Seigneur.',
        6: 'Il s’attend à ce que son salut, lui vienne du Seigneur.',
        7: 'La vérité des justes est auprès de Dieu leur Sauveur; le péché n’habitera pas dans la maison du juste,',
        8: 'Le juste visite toujours sa maison afin d’ôter l’injustice qui la ferait tomber.',
        9: 'Il a expié son erreur dans le jeûne et dans l’humilité de son âme.',
        10: 'Et le Seigneur purifie tout homme saint et sa maison.',
        11: 'Le pécheur offense le Seigneur et il maudira sa vie, le jour de sa génération et les douleurs (qui ont accompagné sa naissance).',
        12: 'Il a ajouté péché sur péché en sa vie.',
        13: 'Il est tombé parce que ses actions sont mauvaises, et la perdition du pécheur sera irréparable pour l’éternité.',
        14: 'Et le Seigneur, lorsqu’il visite les justes, ne se souviendra pas de lui.',
        15: 'Tel est la part du pécheur pour tous les siècles.',
        16: 'Mais ceux qui craignent le Seigneur ressusciteront pour la vie éternelle, et leur vie sera dans la lumière du Seigneur, et elle ne cessera plus.',
    },
    4: {
        1: 'Tu es assis dans le conseil, profane, mais ton cœur a longtemps été éloigné de Dieu, exaspérant par tes transgressions le Dieu d’Israël.',
        2: 'Tenant des discours inutiles, rude dans tes paroles, condamnant les pécheurs dans ton jugement.',
        3: 'Et sa main est toujours sur le pécheur comme étant animée de zèle, tandis qu’il se rend coupable par ses péchés multipliés et ses incontinences.',
        4: 'Ses yeux s’arrêtent indistinctement sur toute femme, sa langue affirme des mensonges avec serment.',
        5: 'Il pêche dans le secret et dans les lieux cachés, comme s’il n’était pas vu; ses yeux s’adressent à toutes les femmes, son langage est empreint du signe de la malice.',
        6: 'Il est prompt à entrer dans toute maison pour se réjouir, comme s’il n’était pas plein d’iniquités.',
        7: 'Détruis, Seigneur, les pécheurs qui simulent la sainteté; frappe leur chair de corruption et leur vie de détresse.',
        8: 'Révèle les œuvres des hommes qui s’étudient à plaire aux hommes.',
        9: 'Et les saints justifieront les jugements de leur Dieu, qui a ôté les pécheurs de devant la face des justes,',
        10: 'Ainsi que le flatteur qui parle de la foi d’une manière trompeuse.',
        11: 'Et leurs yeux sont toujours fixés dans la maison de l’homme quí prospère; déruits leur sagesse, et montre ce que c’est que les paroles des pécheurs.',
        12: 'Leurs paroles ne sont que tromperies afin d’agir selon leur concupiscence coupable.',
        13: 'Le Seigneur s’est enfin levé, il est venu détruire l’homme inique et l’a jeté dans la détresse et l’indigence à cause de sa concupiscence.',
        14: 'Le pécheur trompe dans ses discours comme s’il n’y avait personne pour le voir et le juger.',
        15: 'Il est rempli de son iniquité; son âme est insatiable.',
        16: 'Seigneur, que sa portion devant toi soit l’ignominie; que sa fin soit dans l’affliction et son entrée dans le malheur.',
        17: 'Que sa vie, Seigneur, circule dans les douleurs, la pauvreté et la détresse; que son sommeil soit dans les douleurs, et son réveil dans l’indigence.',
        18: 'Que le sommeil soit éloigné de lui pendant la nuit; qu’il tombe dans l’ignominie à chaque œuvre de ses mains.',
        19: 'Qu’il rentre dans sa maison n’ayant rien dans ses mains, et que sa maison soit privée de tout ce qui pourrait rassasier son âme.',
        20: 'Que sa vieillesse s’écoule dans la solitude et sans rejetons.',
        21: 'Les chairs de ceux qui s’étudient à plaire aux hommes ont été déchirées par les bêtes féroces: les ossements des pécheurs restent exposés au soleil dans l’ignominie.',
        22: 'Que les corbeaux arrachent les yeux des hommes trompeurs.',
        23: 'Parce qu’ils ont détruit une multitude de maisons, réduisant leurs possesseurs à l’ignominie, et parce qu’ils ont dissipé leurs biens au gré de leur concupiscence.',
        24: 'Et ils ne se sont pas souvenus de Dieu, et ils n’ont pas craint Dieu dans tout ce qu’ils faisaient.',
        25: 'Et ils ont exaspéré le Seigneur, et ils l’ont irrité jusqu’à ce qu’il les ôte de la terre, parce qu’ils font simulation de vivre selon la justice.',
        26: 'Heureux ceux qui, dans leur innocence, craignent le Seigneur.',
        27: 'Le Seigneur les délivrera des hommes trompeurs et pécheurs: il nous délivrera de tous les scandales de l’homme injuste.',
        28: 'Détruis, Seigneur, ceux qui, dans leur orgueil, commettent toute injustice; car tu es un juge équitable et puissant.',
        29: 'Le Seigneur est notre Dieu dans la justice; que ta miséricorde, Seigneur, s’étende sur tous ceux qui t’aiment.',
    },
    5: {
        1: 'Seigneur Dieu, que ton nom soit béni avec transport, du milieu de ceux qui connaissent tes jugements équitables.',
        2: 'Parce que tu es miséricordieux et bon, le refuge des hommes.',
        3: 'Lorsque je crierai vers toi, ne garde pas le silence à mon égard.',
        4: 'Parce que l’homme ne pourra prendre les dépouilles d’un homme puissant.',
        5: 'Et qui pourra s’emparer de toutes les choses que tu as faites, si ce n’est celui à qui tu les as données?',
        6: 'Car l’homme et ses actions sont pesées dans la balance, Seigneur, et il ne peut s’élever contre ton jugement.',
        7: 'Lorsque nous serons dans l’affliction, nous t’invoquerons pour que tu nous assistes, et tu ne repousseras pas notre prière, parce que tu es notre Dieu.',
        8: 'N’appesantis pas ta main sur nous, de peur que la nécessité ne nous fasse tomber dans le péché.',
        9: 'Et, quoique tu ne nous assistes pas, nous ne nous éloignerons pas de toi, mais nous viendrons vers toi.',
        10: 'Si j’ai faim, je viendrai vers toi, Seigneur, et tu me donneras (des aliments).',
        11: 'Tu nourris les oiseaux et les poissons, tu fais tomber la pluie dans le désert pour préparer la nourriture pour tout être vivant.',
        12: 'Et, s’ils ont faim, ils élèvent vers toi leurs faces.',
        13: 'Tu nourris, mon Dieu, les rois et les princes et les peuples.',
        14: 'Et tu m’exauceras, car qui est bon et doux si ce n’est toi? Tu réjouis l’âme des humbles lorsque tu ouvres ta main dans la miséricorde.',
        15: 'Ta bonté s’étend sur l’homme comme sur un ami, et tu le soutiens dans ses épreuves.',
        16: 'Tu accordes tes dons avec bonté et largesse, et celui qui met son espoir en toi, Seigneur, ne s’enorgueillira pas de tes dons.',
        17: 'Ta miséricorde, Seigneur, s’étend sur toute la terre.',
        18: 'Heureux celui dont Dieu se souvient, et qui observe la modération dans la frugalité.',
        19: 'Si l’homme est dans l’abondance, il pèche.',
        20: 'Une médiocrité suffisante dans la justice, et la bénédiction du Seigneur pour être rassasié dans la justice.',
        21: 'Ceux qui craignent le Seigneur se sont réjouis; la bonté s’étend sur Israel dans ton royaume.',
        22: 'Que la gloire du Seigneur soit bénie; car il est notre roi.',
    },
    6: {
        1: 'Heureux l’homme dont le cœur est préparé à invoquer le nom du Seigneur.',
        2: 'Lorsqu’il se souviendra du nom du Seigneur, il sera sauvé.',
        3: 'Ses voies seront dirigées par le Seigneur, et les œuvres de ses mains seront aimées du Seigneur.',
        4: 'Il ne sera pas troublé par les visions fâcheuses de ses songes.',
        5: 'Son âme ne s’effrayera point dans le passage des fleuves et dans les tempêtes.',
        6: 'Il s’est levé de son sommeil, et il a béni le nom du Seigneur.',
        7: 'Dans la constance de son cœur, il a béni le nom de son Dieu, et il a prié la face du Seigneur pour toute sa maison.',
        8: 'Et le Seigneur a écouté la prière de tout homme qui est dans la crainte de Dieu, et le Seigneur exaucera toutes les demandes de l’âme qui espère en lui.',
        9: 'Que le Seigneur soit béni, lui qui fait miséricorde a ceux qui l’aiment dans la vérité.',
    },
    7: {
        1: 'Ne t’éloigne pas de nous, ô mon Dieu! de peur que ceux qui nous haïssent sans raison ne se jettent sur nous.',
        2: 'Tu les a repoussés, Seigneur, pour que leur pied ne foule pas l’héritage qui est consacré à ta sainteté.',
        3: 'Châtie-nous selon ta volonté, et ne nous livre pas aux gentils.',
        4: 'Ne nous envoie pas la mort avec l’ordre de nous frapper; épargne-nous, Seigneur, parce que tu es miséricordieux, et que ta colère ne nous consume pas.',
        5: 'Lorsque ton nom habitera au milieu de nous, nous obtiendrons miséricorde.',
        6: 'Et les nations (infidèles) ne prévaudront pas contre nous, parce que tu es notre protecteur.',
        7: 'Et nous t’invoquerons, et tu nous exauceras.',
        8: 'Parce que tu auras pitié de la race d’Israël dans l’éternité, et que tu ne nous repousseras pas, et que tu ne nous tiendras',
        9: 'Tu nous diriges dans le temps où tu viens nous secourir, ayant pitié du peuple de Jacob, dans le jour que tu lui as annoncé.',
    },
    8: {
        1: 'Mon oreille a entendu la tribulation et la voix de la guerre; elle a entendu les cris de la trompette qui sonne le carnage et la mort.',
        2: 'La voix d’un peuple nombreux, comme les vents dont l’impétuosité est extrême, comme les tourbillons d’un grand feu qui parcourt le désert.',
        3: 'Et j’ai dit dans mon cœur: Est-ce que Dieu ne le jugera pas?',
        4: 'J’ai entendu une voix en Jérusalem, la ville de la sanctification.',
        5: 'Mes reins se sont brisés en entendant cette voix; mes genoux se sont rompus.',
        6: 'Mon cœur a tremblé; mes os se sont troublés,',
        7: 'Et j’ai dit: Ils dirigent leurs voies selon la justice, ceux qui contemplent les jugements de Dieu; j’ai contemplé ces jugements depuis la création du ciel et de la terre; j’ai justifié Dieu en ses jugements qui sont depuis tous les siècles.',
        8: 'Dieu a révélé les péchés des méchants en présence du soleil; toute la terre a connu les justes jugements de Dieu.',
        9: 'Il révélera, dans sa colère, les iniquités des méchants cachées dans les ténèbres souterraines.',
        10: 'Le fils s’est mêlé avec sa mère, et le père avec sa fille.',
        11: 'Plusieurs ont commis adultère avec la femme de leur prochain; ils ont fait des pactes sous foi de serment.',
        12: 'Ils ont pillé les choses consacrées à Dieu; ils n’y voient pas d’héritier pour les revendiquer.',
        13: 'Ils ont foulé aux pieds l’autel de Dieu, le souillant de toutes les immondices; et, Jans l’effusion du sang, ils ont souillé les hosties comme des choses profanes.',
        14: 'Ils n’ont pas laissé un péché qu’ils n’aient commis.',
        15: 'C’est pourquoi Dieu a mêlé en eux l’esprit d’erreur; il leur a fait couler jusqu’à l’ivresse le calice de son vin.',
        16: 'Il les a conduits des extrémités de la terre, les frappant fortement.',
        17: 'Il a jugé la guerre à Jérusalem, et en son territoire.',
        18: 'Les princes de la terre sont accourus au-devant de lui; ils lui ont dit avec joie: ta voie a été élargie, venez, entrez en paix.',
        19: 'Ils ont élargi les voies qui étaient difficiles et étroites; ils ont ouvert des portes à Jérusalem; ils ont couronné ses murs.',
        20: 'Il est arrivé comme un père dans la maison de ses fils; il a posé ses pieds avec une grande sécurité.',
        21: 'Il a occupé les murs de Jérusalem et ses tours.',
        22: 'Parce que Dieu l’a conduit avec sécurité dans la déception.',
        23: 'Il a perdu leurs princes dans le conseil; il a versé le sang des habitants de Jérusalem comme de l’eau immonde.',
        24: 'Il a emmené leurs fils et leurs filles parce qu’ils les avaient engendrés dans la profanation.',
        25: 'Ils ont fait selon leurs immondices comme leurs pères.',
        26: 'Ils ont souillé Jérusalem et les choses consacrées au nom du Seigneur.',
        27: 'Dieu a été justifié dans ses jugements, dans les nations de la terre.',
        28: 'Et les saints et Dieu seront comme des agneaux dans leur innocence, au milieu de leurs ennemis.',
        29: 'Louange au Seigneur qui juge toute terre en sa justice.',
        30: 'Et voici, maintenant, Seigneur, que tu nous a montré ton jugement dans ta justice.',
        31: 'Leurs yeux ont vu tes jugements, ô mon Dieu! Nous avons justifié ton nom digue d’hommage dans tous les siècles.',
        32: 'Parce que tu es le Dieu de justice qui juge Israël et qui le corrige.',
        33: 'Tourne, Seigneur, ta miséricorde vers nous et aie pitié de nous.',
        34: 'Réunis Israël par un effet de ta miséricorde et de la bonté, car il est dispersé.',
        35: 'Ta foi est en nous, mais nous avons endurci notre tête, et tu nous a corrigés.',
        36: 'Ne nous méprise pas, Seigneur; que les nations ennemies ne nous méprisent pas, et ne nous trouvent pas privés d’un Rédempteur.',
        37: 'Tu es notre Dieu depuis le commencement, et nous avons espéré en toi, Seigneur.',
        38: 'Et nous te louerons, car tes jugements sont pleins de bonté pour nous.',
        39: 'Pour nous et pour nos fils sois toujours bienveillant, ô Seigneur notre Dieu! nous ne serons point troublés dans l’éternité. 40. Le Seigneur est louable dans ses jugements, dans la bouche des saints. Et toi, Israël, tu es béni du Seigneur, dans tous les siècles.',
    },
    9: {
        1: 'Lorsqu’Israël fut conduit dans une terre étrangère, lorsqu’il s’était éloigné de Dieu son Rédempteur.',
        2: 'Il fut privé de l’héritage que Dieu lui avait donné parmi toutes les nations; Israël fut dispersé selon la parole du Seigneur.',
        3: 'Afin que tu fusses, ô mon Dieu! justifié dans ta justice et selon nos iniquités.',
        4: 'Parce que tu es un juge équitable sur tous les peuples de la terre.',
        5: 'Car tout homme qui commet l’iniquité ne se dérobera pas à ta connaissance.',
        6: 'Et la justice de tes saints est devant tes regards; Seigneur, l’homme ne se dérobera pas à ta connaissance.',
        7: 'Seigneur, tu vois si notre cœur est disposé à faire ce qui est juste, et tu vois ce qu’il y a d’iniquités dans les œuvres de nos mains.',
        8: 'Et tu visites dans ta justice les fils des hommes.',
        9: 'Celui qui fait ce qui est juste amasse un trésor devant le Seigneur, et celui qui commet l’iniquité est lui-même cause de la perte de son âme.',
        10: 'Car les jugements du Seigneur sont dans la justice selon l’homme et la maison.',
        11: 'Pour qui Dieu montrera-t-il sa bonté, si ce n’est pour ceux qui invoquent le Seigneur?',
        12: 'Il a purifié l’âme dans les péchés, dans la confession, dans les accusations.',
        13: 'Parce que nos fautes sont pour nous et pour nos frères, en toutes choses, un sujet de confusion.',
        14: 'Et à qui le Seigneur remettra-t-il les péchés, si ce n’est aux pécheurs?',
        15: 'Tu béniras les justes, &mon Dieu! et ne les puniras selon leurs péchés, et ta bonté s’étendra sur les pécheurs dans leur pénitence.',
        16: 'Tu es le Dieu d’Israël, et nous sommes à toi; tu ne sépareras pas ta miséricorde de nous, de peur que nos ennemis ne fondent sur nous.',
        17: 'Car tu as choisi la race d’Abraham de préférence à toutes les nations.',
        18: 'Mets ton nom sur nous, Seigneur, et qu’il ne nous manque pas dans l’éternité.',
        19: 'Tu as fait un pacte avec nos pères et une promesse sur nous; nous espérons en toi dans la conversion de nos âmes.',
        20: 'Que la miséricorde du Seigneur soit sur la maison d’Israël dans tous les siècles et jusqu’à la fin.',
    },
    10: {
        1: 'Heureux l’homme dont le Seigneur se souvient pour le reprendre et qui, sous les coups du châtiment, s’est détourné de la voie de la malice, afin qu’il soit purifié de son péché.',
        2: 'Celui qui tend le aos aux coups, sera purifié; le Seigneur est bon pour ceux qui endurent le châtiment.',
        3: 'Il rendra droits les chemins des justes, et il ne déviera pas dans ses châtiments.',
        4: 'La miséricorde du Seigneur s’étend sur ceux qui l’aiment dans la vérité; le Seigneur se souviendra de ses serviteurs dans sa miséricorde.',
        5: 'Le témoignage dans la loi du testament éternel est un témoignage du Seigneur, pour qu’il invite les soutiens des hommes.',
        6: 'Notre Seigneur est juste et saint dans ses jugements dans l’éternité: Israël bénira avec allégresse le nom du Seigneur.',
        7: 'Et les saints le confesseront dans l’assemblée des peuples, et Dieu se souviendra des peuples dans l’allégresse d’Israël.',
        8: 'Parce que le Seigneur est miséricordieux et doux dans tous les siècles, et les Synagogues d’Israël glorifieront le nom du Seigneur.',
        9: 'Que le salut du Seigneur soit sur la maison d’Israël, dans une allégresse éternelle.',
    },
    11: {
        1: 'Sonnez de la trompette en Sion, trompette de la signification des saints.',
        2: 'Prêchez dans Jérusalem la croix et celui qui annonce de bonnes choses, parce que Dieu s’est souvenu des enfants d’Israël dans leurs épreuves.',
        3: 'Tiens-toi élevée, Jérusalem et vois tes fils dans l’Orient et dans l’Occident réunis par le Seigneur.',
        4: 'Ils viendront poussés par l’aquilon; la joie de leur Dieu les appellera du côté du midi; Dieu les rassemblera des pays les plus éloignés.',
        5: 'Il abaissera pour eux au niveau des plaines les montagnes les plus élevées.',
        6: 'Les collines fuiront à leur approche; les bois les couvriront pendant leur voyage.',
        7: 'Tout bois odoriférant sera en abondance devant eux, o mon Dieu! afin qu’Israël s’achemine dans les imitations de la gloire de son Dieu.',
        8: 'Revêts-toi, Jérusalem, des vêtements de ta gloire; prépare la robe de ta sanctification, parce que Dieu a parlé avec bonté à Israël, lui faisant des promesses pour l’éternité et au delà.',
        9: 'Le Seigneur fera ce qu’il a annoncé pour Israël et Jérusalem; il élèvera Jérusalem pour l’éternité et au delà.',
    },
    12: {
        1: 'Seigneur, délivre-nous donc de l’homme prévaricateur et injuste, de la langue du pécheur et du perfide, de celle qui profère des mensonges et des fourberies.',
        2: 'Les paroles de la langue de l’homme inique qui fait les œuvres de l’injustice, sont comme le feu dans l’aire, lorsqu’il incendie la paille.',
        3: 'Il remplira tout ce qui l’entoure des maux causés par sa langue perfide; détruis, Seigneur, les arbres du pécheur rempli de joie.',
        4: 'Confonds les maisons iniques et ferme les livres du médisant; éloigne, Seigneur, ee tison ardent, éloigne-le des innocents.',
        5: 'Que la langue qui médit périsse et qu’elle ne fasse aucun mal aux saints.',
        6: 'Que le Seigneur protège l’âme qui garde le silence et qui déteste l’injustice, et que le Seigneur dirige dans la maison de la paix l’homme qui fait le bien.',
        7: 'Que le salut du Seigneur soit à toujours sur Israël, son fils.',
        8: 'Et que les pécheurs périssent de devant la face du Seigneur, et que les saints du Seigneur héritent de ce qu’il leur a promis.',
    },
    13: {
        1: 'La droite du Seigneur nous a soutenus, la droite du Seigneur nous a épargnés.',
        2: 'Le bras de Dieu nous a sauvés de la famine et de la mort des pécheurs.',
        3: 'Des bêtes féroces accouraient sur les voies qu’ils suivaient, elles déchiraient leurs chairs et broyaient leurs os sous leurs dents, et Dieu nous a délivrés de tous ces maux.',
        4: 'L’impie a été troublé à cause ses péchés; il a craint d’être saisi chargé de toutes ses fautes.',
        5: 'La punition du pécheur est terrible, mais le juste sera exempt de tous ces maux.',
        6: 'Car la correction du juste qui a erré dans l’ignorance n’est pas semblable à la punition infligée au pécheur.',
        7: 'Le juste sera châtié en saint, afin que le pécheur n’insulte pas un juste.',
        8: 'Car le Seigneur admonestera le juste comme le fils de sa tendresse, et il le punira comme on punit un premier-né.',
        9: 'Car le Seigneur épargnera ses saints, et effacera leurs fautes en les corrigeant, car la vie des justes dure à toujours.',
        10: 'Les pécheurs s’élèveront pour leur perte, et leur mémoire ne se retrouvera plus.',
    },
    14: {
        1: 'Dieu est fidèle à ceux qui l’aiment dans la vérité et qui supportent sa correction, à ceux qui marchent dans la voie de ses préceptes, comme il nous l’a ordonné.',
        2: 'Les saints du Seigneur vivront en lui dans l’éternité; le paradis du Seigneur est le germe de la vie des saints.',
        3: 'Leur plantation est enracinée dans tous les siècles; ils ne seront jamais arrachés parce qu’Israël est la portion et l’hérédité de Dien.',
        4: 'Il n’en est pas ainsi des pécheurs et des injustes qui ont aimé le jour dans la participation de leur péché et dans la pourriture de leur concupiscence',
        5: 'Et ils ne se sont pas souciés de Dieu, mais les vices des hommes sont toujours notés en sa présence, et il connaît les pensées de leur cœur avant qu’elles ne naissent.',
        6: 'Aussi auront-ils pour héritage l’enfer, les ténèbres et la perdition, et ils ne se rencontreront pas dans le jour de la miséricorde des justes.',
        7: 'Mais les saints du Seigneur hériteront de la vie dans l’allégresse.',
    },
    15: {
        1: 'Dans mon affliction, j’ai invoqué le nom du Seigneur; j’ai mis mon espoir dans l’assistance du Dieu de Jacob, et j’ai été sauvé.',
        2: 'Car tu es, Seigneur, l’espoir et le refuge des pauvres.',
        3: 'Quelle puissance a l’homme, Seigneur, à moins qu’il ne te confesse dans la vérité? 4. Et que peut-il s’il ne confesse ton âme? 5. Qu’il chante tes hommages dans la joie de son cœur, qu’il t’offre les prémices de ses lèvres inspirées par un cœur saint et juste.',
        6: 'Agissant ainsi, il sera préservé du mal dans l’éternité; la flamme du feu et la colère des injustes ne l’atteindra point.',
        7: 'Car il est venu de devant la face du Seigneur, et il a surpris les pécheurs afin de',
        8: 'Car le signe du Seigneur est sur les justes, et leur sert de salut; la famine, le glaive et la mort s’éloignent d’eux.',
        9: 'Les pécheurs fuiront loin des saints comme si la famine les poursuivait, et le jugement de Dieu surprendra, comme un chasseur habile, ceux qui commettent l’iniquité.',
        10: 'Car le signe de la perdition est sur leur front.',
        11: 'Et l’héritage des pécheurs est la perdition, et les ténèbres et leurs iniquités les suivront jusqu’aux enfers.',
        12: 'Leur héritage ne se trouvera pas dans leurs fils.',
        13: 'Les iniquités désoleront les maisons des pécheurs, et ils périront pour l’éternité dans le jour du jugement de Dieu.',
        14: 'Lorsque Dieu invitera la terre dans son jugement afin de traiter dans le temps éternel les pécheurs selon leurs mérites.',
        15: 'Mais ceux qui craignent le Seigneur obtiendront miséricorde, et ils vivront dans la miséricorde de leur Dieu.',
    },
    16: {
        1: 'Lorsque mon âme dormait, Seigneur, j’ai été au moment de m’écarter de Dieu dans l’accablement du sommeil.',
        2: 'Lorsque j’étais loin de Dieu, mon âme est presque arrivée à la mort à cause des portes de l’enfer qui attendent le pécheur.',
        3: 'Mon âme se serait écartée du Seigneur Dieu d’Israël, si le Seigneur ne m’avait prévenu par sa miséricorde qui est éternelle.',
        4: 'Le Sauveur m’a frappé comme d’un éperon; mon défenseur m’a préservé en tout temps.',
        5: 'Je te célébrerai, mon Dieu, car tu as veillé sur mon salut, et tu ne me confondras pas avec les pécheurs dans leur perdition.',
        6: 'N’éloigne pas ta miséricorde de moi, Seigneur; n’éloigne pas ta miséricorde de mon cœur jusqu’à la mort.',
        7: 'Préserve-moi, mon Dieu, du péché et de toute femme méchante qui est un sujet de chute pour l’insensé.',
        8: 'Que la beauté de la femme perverse ne me séduise pas et que je sois préservé du péché.',
        9: 'Dirige les œuvres de mes mains vers ta demeure, et guide mes pas dans la mémoire.',
        10: 'Protége ma langue et mes lèvres dans les paroles de la vérité; éloigne de moi la colère et la fureur insensée.',
        11: 'Eloigne de moi le murmure et l’abattement dans la tribulation; si j’ai péché, corrige-moi pour que je revienne à toi.',
        12: 'Affermis mon âme dans la joie de te servir; si tu fortifies mon âme, Seigneur, ce don me suffit.',
        13: 'Qui soutiendra tes châtiments, si ta miséricorde ne les adoucit?',
        14: 'Lorsque l’âme était chatiée dans les mains de sa pourriture, ton bon plaisir vint soutenir sa chair dans la tribulation de la détresse.',
        15: 'Le juste sera soutenu dans ses épreuves, il obtiendra la miséricorde du Seigneur.',
    },
    17: {
        1: 'Seigneur, tu es notre roi pour l’éternité, et c’est en toi, ô mon Dieu, que notre âme sera glorifiée.',
        2: 'Quelle est la durée de la vie de l’homme sar la terre auprès du temps du Seigneur? c’est en lui que nous devons mettre notre espérance.',
        3: 'Nous espérons en Dieu notre sauveur, car la puissance de notre Dieu s’étend dans tous les siècles, accompagnée de sa miséricorde.',
        4: 'Et le règne de notre Dieu s’étend dans l’éternité, au-dessus des nations qu’il juge.',
        5: 'Seigneur, tu as choisi David pour roi d’Israël, et tu lui as fait un serment en faveur de sa race pour tous les siècles; tu as promis que son royaume ne déclinerait pas en la présence.',
        6: 'Les pécheurs se sont élevés contre nous à cause de nos péchés; ils se sont jetés sur nous; ceux qui ne te connaissent pas nous ont expulsés; ils nous ont enlevé avec violence ce que nous possédions.',
        7: 'Ils n’ont pas glorifié ton nom digne d’honneur; dans leur orgueil ils ont mis un diadème sur leur tête comme symbole de leur puissance.',
        8: 'Ils ont renversé le trône de David dans l’exaltation de leur orgueil; tu les renverseras, Seigneur, et tu ôteras leur race de dessus la terre.',
        9: 'Lorsque tu exciteras contre eux l’homme qui est de la race des guerriers,',
        10: 'Tu les traiteras selon leurs péchés, Seigneur; qu’ils trouvent selon leurs œuvres.',
        11: 'Dieu aura pitié d’eux selon leurs œuvres; il a scruté leur race et il ne les a pas délivrés.',
        12: 'Le Seigneur est fidèle dans tous les jugements qu’il rend sur la terre',
        13: 'Le vent a désolé notre pays; ils ont renversé le jeune homme et le vieillard et leurs enfants.',
        14: 'Le Seigneur les a frappés dans sa colère jusqu’à la fin du jour; il n’a point épar gné les princes de la terre.',
        15: 'Nos ennemis se livrent à l’orgueil et leur cœur est bien loin de notre Dieu.',
        16: 'Et de tout ce qu’il a fait à Jérusalem; les nations ont dans leurs cités rendu hommages à leurs dieux.',
        17: 'Les enfants de l’alliance ont été conduits au milieu des nations; il n’y avait plus personne qui agit, au milieu de Jérusalem, selon la miséricorde et la vérité',
        18: 'Ceux qui aiment les assemblées des saints ont fui loin d’eux comme des passereaux s’envolent de leur nid.',
        19: 'Ils ont été frappés dans les déserts pour que leur âme fût préservée du mal, et à peine un seul a-t-il échappé en conservant la vie.',
        20: 'Ils ont été dispersés sur toute la terre par les hommes iniques, parce que le ciel a cessé de répandre la pluie sur la terre.',
        21: 'Les fontaines éternelles ont été fermées parce qu’il n’y a parmi eux personne qui agisse selon la justice; depuis leur prince jusqu’au dernier du peuple, il n’y a parmi eux un seul qui ne soit pécheur.',
        22: 'Le roi transgresse la loi, et le peuple est dans le péché.',
        23: 'Vois, Seigneur, et rends à ton peuple son roi, le fils de David; tu enverras ton fils pour régner en Israël.',
        24: 'Ceins-le de force afin qu’il renverse les princes injustes.',
        25: 'Purifie Jérusalem des nations qui marchent dans la perdition, et traite-les selon ta justice.',
        26: 'Repousse les pécheurs de l’héritage, brise l’orgueil des pécheurs, détruis tout leur pouvoir comme une baguette de fer brise des vases de terre.',
        27: 'Que la parole de la bouche de ton envoyé subjugue les nations iniques; que les nations fuient devant son visage et reprends les pécheurs dans la parole de son cœur.',
        28: 'Et il rassemblera le peuple saint qu’il conduira selon la justice, et il rendra la justice aux tribus du peuple sanctifié par le Seigneur.',
        29: 'Il ne permettra pas à l’injustice d’habiter au milieu d’eux, et tout homme expert en malice n’habitera pas avec eux.',
        30: 'Il saura qu’ils sont tous les fils de son Dieu, et il les distribuera dans leurs tribus sur la terre.',
        31: 'Et l’étranger n’habitera plus avec eux; il jugera les nations et les peuples dans la sagesse de sa justice.',
        32: 'Et il aura sous son joug les peuples des nations pour le servir, et il sera glorifié; sa renommée s’étendra sur toute la terre.',
        33: 'Et il purifiera Jérusalem, la sanctifiant et la rétablissant comme elle était dès le commencement.',
        34: 'Afin que les nations viennent des extrémités de la terre parmi sa gloire, en apportant des présents;',
        35: 'Pour voir la gloire du Seigneur; il est le roi juste que Dieu a instruit.',
        36: 'Et, de son temps, il n’y a pas d’injustice au milieu des hommes, parce que tous sont muets, et que leur roi est le Christ, le Seigneur.',
        37: 'Il ne met pas son espoir dans le cheval, ni dans l’art, ni dans les machines de guerre; il n’a pas ramassé de l’or et de l’argent pour faire la guerre, et il n’a pas confiance dans les événements de la guerre.',
        38: 'Le Seigneur est son roi; son espoir est en Dieu; il aura pitié de toutes les nations qui sont en sa présence dans la frayeur.',
        39: 'Il fera trembler la terre jusque dans l’éternité par la parole de sa bouche.',
        40: 'Il bénira le peuple de Dieu dans la sagesse avec allégresse.',
        41: 'Et lui-même sera pur de péchés pour gouverner un grand peuple, pour réprimander les princes; il détruira les pécheurs par la puissance de sa parole.',
        42: 'Et il conservera toute sa puissance devant Dieu, parce que Dieu lui a donné de la force dans l’Esprit saint, et lui a donné la sagesse et la prudence avec la justice.',
        43: 'La bénédiction du Seigneur sera sur lui et lui conservera sa force, et il ne sera point affaibli.',
        44: 'Son espérance est dans le Seigneur, et qui a de la puissance contre lui? Il est fort en ses œuvres et puissant dans la crainte de Dieu.',
        45: 'Il fera paître le troupeau du Seigneur dans la foi et la justice; il ne permettra pas que la dissolution se répande dans ses pâturages.',
        46: 'Il les conduira tous dans la sainteté; il n’y aura point parmi eux l’orgueil d’exercer de la domination.',
        47: 'Il sera l’éclat du roi d’Israël que Dieu connaît, et qu’il suscitera dans la maison d’Israël pour la rétablir.',
        49: 'Ses discours sont comme les paroles des saints au milieu des peuples sanctifiés.',
        50: 'Heureux ceux qui naissent dans ces jours pour voir le bonheur d’Israël dans la réunion des tribus que Dieu accomplira.',
        51: 'Étends Seigneur, la miséricorde sur Israël. Il nous a délivrés de l’impureté de ses ennemis profanes; le Seigneur est notre roi dans tous les siècles.',
    },
    18: {
        1: 'Seigneur, ta miséricorde s’étend sur l’œuvre de tes mains pour l’éternité.',
        2: 'Ta bonté a fait de riches présents aux fils d’Israël; tes yeux se sont arrêtés sur eux et tu ne les abandonnes pas.',
        3: 'Que tes oreilles entendent la demande du pauvre qui met son espoir en toi; tes jugements s’étendent sur toute la terre avec ta miséricorde.',
        4: 'Et ton affection s’étend sur la race d’Abraham, sur le fils d’Israël; ton attachement pour eux est comme celui d’un homme pour un fils unique.',
        5: 'Détourne l’âme obéissante des péchés qu’elle commettrait dans l’ignorance.',
        6: 'Purifie, Seigneur, Israël dans le jour de ta miséricorde; donne-lui ta bénédiction, dans le jour que tu auras choisi pour le règne du Christ.',
        7: 'Heureux ceux qui sont nés dans les jours qui leur permettront de voir le bien que fera le Seigneur à la génération future.',
        8: 'Le Christ gouvernera Israël dans la crainte de Dieu, dans la sagesse de l’esprit, dans la justice et la force.',
        9: 'Il dirigera les hommes dans la voie de la justice, leur inspirant à tous la crainte de Dieu.',
        10: 'Une génération bonne dans la crainte de Dieu, dans les jours de la miséricorde.',
        11: 'Notre Dieu est grand et glorieux; il habite dans les régions les plus élevées.',
        12: 'Il a réglé dans sa puissance les luminaires dans le cours des heures et ils ne s’écarteront pas de la voie qu’il leur a tracée.',
        13: 'Leur vie s’effectue chaque jour dans la crainte de Dieu, depuis le jour où Dieu les a créés jusque dans tous les siècles.',
        14: 'Et ils ne s’en sont pas écartés depuis le jour de leur création, dans les générations anciennes; ils n’ont pas dévié de leur voie, à moins que Dieu ne leur ait commandé d’obéir aux ordres de ses serviteurs.',
    },
}
